# Printed757–758; expansions about0 and exact endpoint conventions.
def sf(text,label='Power series'):return C(text,'−('+text+')','2('+text+')',label=label)
def power(i,term,rad,interval=None,why='',limited=False):
 fs=[sf(term),N(rad,'Radius') if not isinstance(rad,str) else C(rad,'0','∞',label='Radius')]
 if interval:fs.append(C(interval,'Only x=0','All real x',label='Interval of convergence'))
 put(9,i,*fs,why=why or 'Obtain the series from the geometric expansion by substitution, multiplication, differentiation or integration inside its radius. Test any requested endpoints separately.',limited=limited)
put(9,1,N(10,'Radius'),why='Termwise differentiation preserves radius, though endpoint convergence can change.')
put(9,2,C('Converges for every |x|<2; no endpoint conclusion follows from the given information','Must diverge at±2','Must converge for every real x'),why='Termwise integration preserves the radius and can improve endpoints, but the data do not specify them.',limited=True)
for row in [(3,'Σ_(n=0)^∞(−1)^n x^n',1,'(−1,1)'),(4,'5Σ_(n=0)^∞4^n x^(2n)',S.Rational(1,2),'(−1/2,1/2)'),(5,'Σ_(n=0)^∞2x^n/3^(n+1)',3,'(−3,3)'),(6,'Σ_(n=0)^∞4(−2)^n x^n/3^(n+1)',S.Rational(3,2),'(−3/2,3/2)'),(7,'Σ_(n=0)^∞(−1)^n x^(4n+2)/16^(n+1)',2,'(−2,2)'),(8,'Σ_(n=0)^∞(−2)^n x^(2n+1)',1/S.sqrt(2),'(−1/sqrt(2),1/sqrt(2))'),(9,'1−(3/2)Σ_(n=0)^∞(−x/2)^n',2,'(−2,2)'),(10,'Σ_(n=0)^∞(−1)^n[x^(2n)/a^(2n+1)+x^(2n+1)/a^(2n+2)]','a','(−a,a)'),(11,'−Σ_(n=0)^∞[1+1/3^(n+1)]x^n',1,'(−1,1)'),(12,'Σ_(n=0)^∞(−1)^n[1+1/2^(n+1)]x^n',1,'(−1,1)')]:power(*row)
put(9,13,sf('Σ_(n=0)^∞(−1)^n(n+1)x^n','(a)'),N(1,'(a) Radius'),sf('Σ_(n=0)^∞(−1)^n(n+1)(n+2)x^n/2','(b)'),sf('Σ_(n=0)^∞(−1)^n(n+1)(n+2)x^(n+2)/2','(c)'),why='Differentiate the reciprocal series once and twice; multiply by x² for(c).')
put(9,14,sf('−Σ_(n=1)^∞x^n/n','(a)'),N(1,'(a) Radius'),sf('−Σ_(n=1)^∞x^(n+1)/n','(b)'),sf('Σ_(n=1)^∞1/(n2^n)','(c) ln2'),why='Integrate1/(1−x) and fix the constant at0, then substitute x=1/2.')
for row in [(15,'ln5−Σ_(n=1)^∞x^n/(n5^n)',5),(16,'Σ_(n=0)^∞(−1)^n x^(6n+5)/(2n+1)',1),(17,'Σ_(n=0)^∞(−1)^n(n+1)4^n x^(n+1)',S.Rational(1,4)),(18,'Σ_(n=0)^∞(n+1)(n+2)x^(n+3)/2^(n+4)',2),(19,'Σ_(n=0)^∞(2n+1)x^n',1),(20,'Σ_(n=1)^∞n²x^n',1)]:power(*row)
for row in [(21,'Σ_(n=0)^∞(−1)^n x^(2n+2)',1,'(−1,1)'),(22,'Σ_(n=1)^∞(−1)^(n−1)x^(4n)/n',1,'[−1,1]'),(23,'2Σ_(n=0)^∞x^(2n+1)/(2n+1)',1,'(−1,1)'),(24,'Σ_(n=0)^∞(−1)^n(2x)^(2n+1)/(2n+1)',S.Rational(1,2),'[−1/2,1/2]')]:power(*row,limited=True)
for i,series in [(25,'C+Σ_(n=0)^∞t^(8n+2)/(8n+2)'),(26,'C+Σ_(n=0)^∞(−1)^n t^(3n+2)/(3n+2)'),(27,'C+Σ_(n=1)^∞(−1)^(n−1)x^(n+3)/[n(n+3)]'),(28,'C+Σ_(n=0)^∞(−1)^n x^(2n+1)/(2n+1)²')]:power(i,series,1)
for i,f,b in [(29,lambda z:z/(1+z**3),mp.mpf('.3')),(30,lambda z:mp.atan(z/2),mp.mpf('.5')),(31,lambda z:z*mp.log(1+z*z),mp.mpf('.2')),(32,lambda z:z*z/(1+z**4),mp.mpf('.3'))]:put(9,i,N(mp.quad(f,[0,b]),'Integral to six decimal places',tol=.00000051),why='Integrate the power series term by term on the stated interval; direct high-precision quadrature independently checks the numeric result.')
put(9,33,N(mp.atan(mp.mpf('.2')),'arctan(.2) to five decimal places',tol=.0000051),why='Use x−x³/3+x⁵/5−… with next-term error bound.')
put(9,34,C('f″=−f, after differentiating the entire series twice and shifting the index','f″=f','f′=f'),limited=True)
put(9,35,C('Each coefficient in x²J₀″+xJ₀′+x²J₀ cancels','Only the constant coefficient cancels','The expression equals1',label='(a)'),N(mp.quad(lambda z:mp.besselj(0,z),[0,1]),'(b) Integral to3decimal places',tol=.00051),limited=True)
put(9,36,C('x²J₁″+xJ₁′+(x²−1)J₁=0 by coefficient cancellation','The expression equals x','J₁ is identically zero',label='(a)'),C('J₀′=−J₁ after shifting the differentiated sum index','J₀′=J₁','J₀′=−J₀',label='(b)'),limited=True)
put(9,37,C('f′=f by termwise differentiation and index shift','f′=−f','f′=1',label='(a)'),C('f=e^x because f′=f and f(0)=1','f=2e^x','f=e^(−x)',label='(b)'),limited=True)
put(9,38,C('Σf_n converges absolutely for all real x by |sin nx|/n²≤1/n²','Only x=0','It diverges everywhere',label='Original series'),C('At x=2kπ the first derivative series isΣ1/n and diverges','The derivative series always converges','It vanishes there',label='First derivatives'),C('Second derivative series converges exactly when x=kπ, k any integer','Only when x=2kπ','Every real x',label='Second derivatives'),why='Second derivatives are−sin(nx). These terms approach0 only for x an integer multiple ofπ; then every term is0.',limited=True)
put(9,39,C('[−1,1]','(−1,1)','[0,1]',label='f'),C('[−1,1)','(−1,1]','[−1,1]',label='f′'),C('(−1,1)','[−1,1]','All real x',label='f″'))
put(9,40,F(1/(1-x)**2,'(a)'),F(x/(1-x)**2,'(b)(i)'),N(2,'(b)(ii)'),F(2*x*x/(1-x)**3,'(c)(i)'),N(4,'(c)(ii)'),N(6,'(c)(iii)'),why='Differentiate the geometric series inside |x|<1; multiply by x or x² and evaluate at1/2.')
put(9,41,C('Substitute x=1/sqrt(3) in arctan x=Σ(−1)^n x^(2n+1)/(2n+1), then multiply by6','Substitute x=sqrt(3) into a series outside its radius','Set x=1 and multiply by2'),limited=True)
put(9,42,N(pi/(3*S.sqrt(3)),'(a) Integral'),C('1/(x²−x+1)=(x+1)/(x³+1)','1/(x²−x+1)=(x−1)/(x³+1)','The factors cannot be combined',label='(b) Factorization'),sf('Σ_(n=0)^∞(−1)^n x^(3n)','(b) Series for1/(1+x³), |x|<1'),C('Integrate(x+1) times this series from0to1/2, then multiply by3sqrt(3)','Differentiate and evaluate at1','Discard all odd terms',label='(b) Proof step'),limited=True)
